// ============================================================
//  Polygon simplification (Ramer–Douglas–Peucker)
//  Drops intermediate outline points that barely change the shape.
// ============================================================
static float pointSegDist(float px, float pz,
                          float ax, float az, float bx, float bz)
{
    float dx = bx - ax, dz = bz - az;
    float len2 = dx * dx + dz * dz;
    if(len2 < 1e-8f)
    {
        float ex = px - ax, ez = pz - az;
        return std::sqrt(ex * ex + ez * ez);
    }
    float t = std::max(0.f, std::min(1.f, ((px - ax) * dx + (pz - az) * dz) / len2));
    float qx = ax + t * dx, qz = az + t * dz;
    float ex = px - qx, ez = pz - qz;
    return std::sqrt(ex * ex + ez * ez);
}

static void dpKeep(const float pts[][2], int i0, int i1, float eps,
                   std::vector<int>& keep)
{
    if(i1 <= i0 + 1)
        return;
    float maxD = 0.f;
    int idx = -1;
    for(int i = i0 + 1; i < i1; ++i)
    {
        float d = pointSegDist(pts[i][0], pts[i][1],
                               pts[i0][0], pts[i0][1],
                               pts[i1][0], pts[i1][1]);
        if(d > maxD)
        {
            maxD = d;
            idx = i;
        }
    }
    if(maxD > eps && idx >= 0)
    {
        dpKeep(pts, i0, idx, eps, keep);
        keep.push_back(idx);
        dpKeep(pts, idx, i1, eps, keep);
    }
}

static int simplifyOutline(float out[][2], const float pts[][2], int n, float eps)
{
    if(n <= 8)
    {
        for(int i = 0; i < n; ++i)
        {
            out[i][0] = pts[i][0];
            out[i][1] = pts[i][1];
        }
        return n;
    }

    std::vector<int> keep;
    keep.reserve((size_t)n);
    keep.push_back(0);
    dpKeep(pts, 0, n - 1, eps, keep);
    keep.push_back(n - 1);
    std::sort(keep.begin(), keep.end());
    keep.erase(std::unique(keep.begin(), keep.end()), keep.end());

    int m = (int)keep.size();
    for(int i = 0; i < m; ++i)
    {
        int k = keep[(size_t)i];
        out[i][0] = pts[k][0];
        out[i][1] = pts[k][1];
    }
    return m;
}

// ============================================================
//  Triangulation
//  For polygons with <200 pts: ear-clipping (exact, handles concave)
//  Safety: maxIter cap prevents hang on degenerate input
// ============================================================
static std::vector<float> triangulate(const float pts[][2], int n)
{
    std::vector<float> result;
    if(n < 3) return result;
    if(n == 3){
        for(int v=0;v<3;++v){result.push_back(pts[v][0]);result.push_back(pts[v][1]);}
        return result;
    }

    std::vector<int> idx(n);
    for(int i=0;i<n;++i) idx[i]=i;

    // Ensure CCW
    float area=0;
    for(int i=0;i<n;++i){int j=(i+1)%n;area+=pts[i][0]*pts[j][1]-pts[j][0]*pts[i][1];}
    if(area<0) std::reverse(idx.begin(),idx.end());

    auto cross2=[&](int a,int b,int c)->float{
        return (pts[b][0]-pts[a][0])*(pts[c][1]-pts[b][1])
              -(pts[b][1]-pts[a][1])*(pts[c][0]-pts[b][0]);
    };
    auto inTri=[&](int p,int a,int b,int c)->bool{
        float d1=cross2(a,b,p),d2=cross2(b,c,p),d3=cross2(c,a,p);
        return !((d1<0||d2<0||d3<0)&&(d1>0||d2>0||d3>0));
    };

    // cap iterations to n*n to avoid O(n³) hang on degenerate input
    int maxIter=n*n, iter=0;
    while((int)idx.size()>3 && iter++<maxIter){
        bool found=false;
        int sz=(int)idx.size();
        for(int i=0;i<sz;++i){
            int prev=idx[(i+sz-1)%sz],cur=idx[i],next=idx[(i+1)%sz];
            if(cross2(prev,cur,next)<=0.0f) continue;
            bool ear=true;
            for(int j=0;j<sz&&ear;++j){
                int v=idx[j];
                if(v==prev||v==cur||v==next) continue;
                if(inTri(v,prev,cur,next)) ear=false;
            }
            if(ear){
                for(int v:{prev,cur,next}){result.push_back(pts[v][0]);result.push_back(pts[v][1]);}
                idx.erase(idx.begin()+i);
                found=true; break;
            }
        }
        // If no ear found (self-intersecting), fall back to fan from centroid
        if(!found){
            float cx=0,cz=0;
            for(int v:idx){cx+=pts[v][0];cz+=pts[v][1];}
            cx/=idx.size();cz/=idx.size();
            int sz2=(int)idx.size();
            for(int i=0;i<sz2;++i){
                int j=(i+1)%sz2;
                result.push_back(cx);result.push_back(cz);
                result.push_back(pts[idx[i]][0]);result.push_back(pts[idx[i]][1]);
                result.push_back(pts[idx[j]][0]);result.push_back(pts[idx[j]][1]);
            }
            return result;
        }
    }
    if((int)idx.size()==3)
        for(int v:idx){result.push_back(pts[v][0]);result.push_back(pts[v][1]);}
    return result;
}

// ============================================================
//  FlatPoly
// ============================================================
void FlatPoly::build(const float pts[][2], int n,
                     float r, float g, float b, float y)
{
    if(n<3) return;
    float simp[512][2];
    int sn=simplifyOutline(simp,pts,n,0.12f);
    if(sn<3) return;
    std::vector<float> tris=triangulate(simp,sn);
    triCount=(int)tris.size()/6;
    if(triCount==0) return;

    std::vector<float> buf; buf.reserve(triCount*3*9);
    for(int t=0;t<triCount;++t)
        for(int v=0;v<3;++v){
            float px=tris[t*6+v*2],pz=tris[t*6+v*2+1];
            buf.push_back(px);buf.push_back(y);buf.push_back(pz);
            buf.push_back(0.f);buf.push_back(1.f);buf.push_back(0.f);
            buf.push_back(r);buf.push_back(g);buf.push_back(b);
        }

    glGenVertexArrays(1,&vao);glBindVertexArray(vao);
    glGenBuffers(1,&vbo);glBindBuffer(GL_ARRAY_BUFFER,vbo);
    glBufferData(GL_ARRAY_BUFFER,(GLsizeiptr)(buf.size()*sizeof(float)),buf.data(),GL_STATIC_DRAW);
    const GLsizei S=9*sizeof(float);
    glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,S,(void*)0);               glEnableVertexAttribArray(0);
    glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,S,(void*)(3*sizeof(float)));glEnableVertexAttribArray(1);
    glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,S,(void*)(6*sizeof(float)));glEnableVertexAttribArray(2);
    glBindVertexArray(0);
}
void FlatPoly::draw() const{if(!vao)return;glBindVertexArray(vao);glDrawArrays(GL_TRIANGLES,0,triCount*3);glBindVertexArray(0);}
void FlatPoly::cleanup(){if(vbo){glDeleteBuffers(1,&vbo);vbo=0;}if(vao){glDeleteVertexArrays(1,&vao);vao=0;}triCount=0;}

// ============================================================
//  Disc
// ============================================================
void Disc::build(float cx,float cz,float radius,float r,float g,float b,float y,int segs){
    triCount=segs;
    std::vector<float> buf;buf.reserve(segs*3*9);
    auto push=[&](float px,float pz){
        buf.push_back(px);buf.push_back(y);buf.push_back(pz);
        buf.push_back(0.f);buf.push_back(1.f);buf.push_back(0.f);
        buf.push_back(r);buf.push_back(g);buf.push_back(b);
    };
    const float PI2=6.28318530f;
    for(int i=0;i<segs;++i){
        float a0=PI2*i/segs,a1=PI2*(i+1)/segs;
        push(cx,cz);
        push(cx+radius*std::cos(a0),cz+radius*std::sin(a0));
        push(cx+radius*std::cos(a1),cz+radius*std::sin(a1));
    }
    glGenVertexArrays(1,&vao);glBindVertexArray(vao);
    glGenBuffers(1,&vbo);glBindBuffer(GL_ARRAY_BUFFER,vbo);
    glBufferData(GL_ARRAY_BUFFER,(GLsizeiptr)(buf.size()*sizeof(float)),buf.data(),GL_STATIC_DRAW);
    const GLsizei S=9*sizeof(float);
    glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,S,(void*)0);               glEnableVertexAttribArray(0);
    glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,S,(void*)(3*sizeof(float)));glEnableVertexAttribArray(1);
    glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,S,(void*)(6*sizeof(float)));glEnableVertexAttribArray(2);
    glBindVertexArray(0);
}
void Disc::draw() const{if(!vao)return;glBindVertexArray(vao);glDrawArrays(GL_TRIANGLES,0,triCount*3);glBindVertexArray(0);}
void Disc::cleanup(){if(vbo){glDeleteBuffers(1,&vbo);vbo=0;}if(vao){glDeleteVertexArrays(1,&vao);vao=0;}triCount=0;}

// ============================================================
//  BatchedFlat — uploads pre-built vertex data, one draw call
// ============================================================
void BatchedFlat::upload(const std::vector<float>& data){
    vertexCount=(int)data.size()/9;
    if(vertexCount==0)return;
    glGenVertexArrays(1,&vao);glBindVertexArray(vao);
    glGenBuffers(1,&vbo);glBindBuffer(GL_ARRAY_BUFFER,vbo);
    glBufferData(GL_ARRAY_BUFFER,(GLsizeiptr)(data.size()*sizeof(float)),data.data(),GL_STATIC_DRAW);
    const GLsizei S=9*sizeof(float);
    glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,S,(void*)0);               glEnableVertexAttribArray(0);
    glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,S,(void*)(3*sizeof(float)));glEnableVertexAttribArray(1);
    glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,S,(void*)(6*sizeof(float)));glEnableVertexAttribArray(2);
    glBindVertexArray(0);
}
void BatchedFlat::draw() const{if(!vao)return;glBindVertexArray(vao);glDrawArrays(GL_TRIANGLES,0,vertexCount);glBindVertexArray(0);}
void BatchedFlat::cleanup(){if(vbo){glDeleteBuffers(1,&vbo);vbo=0;}if(vao){glDeleteVertexArrays(1,&vao);vao=0;}vertexCount=0;}

// ============================================================
//  Colours
// ============================================================
#define COL_SAND    0.93f,0.85f,0.72f
#define COL_ROAD    0.55f,0.55f,0.55f
#define COL_WATER   0.15f,0.55f,0.85f
#define COL_ROCK    0.40f,0.36f,0.30f
#define COL_GBSAND  0.93f,0.85f,0.72f
#define COL_GBRING  0.55f,0.80f,0.38f
#define COL_GBCEN   0.18f,0.62f,0.16f
#define COL_GREEN   0.16f,0.65f,0.14f
#define COL_BRIDGE  0.55f,0.42f,0.25f
#define COL_HUT     0.75f,0.75f,0.75f
#define COL_FLAG    0.85f,0.08f,0.08f

static const float Y_FLOOR  =0.000f;
static const float Y_ROAD   =0.001f;
static const float Y_WATER  =0.002f;
static const float Y_ROCK   =0.003f;
static const float Y_GBSAND =0.004f;
static const float Y_GBRING =0.005f;
static const float Y_GBCEN  =0.006f;
static const float Y_GREEN  =0.007f;
static const float Y_BRIDGE =0.008f;
static const float Y_HUT    =0.008f;
static const float Y_FLAG   =0.009f;

static std::vector<std::pair<float,float>>
shrinkPoly(const float pts[][2],int n,float amount){
    float cx=0,cz=0;
    for(int i=0;i<n;++i){cx+=pts[i][0];cz+=pts[i][1];}
    cx/=n;cz/=n;
    std::vector<std::pair<float,float>> out(n);
    for(int i=0;i<n;++i){
        float dx=pts[i][0]-cx,dz=pts[i][1]-cz;
        float d=std::sqrt(dx*dx+dz*dz);
        if(d<1e-6f){out[i]={cx,cz};continue;}
        out[i]={cx+dx/d*std::max(0.f,d-amount),cz+dz/d*std::max(0.f,d-amount)};
    }
    return out;
}
static void buildShrunk(FlatPoly &poly,const float pts[][2],int n,
                        float shrink,float r,float g,float b,float y){
    auto inner=shrinkPoly(pts,n,shrink);
    std::vector<float> flat;flat.reserve(inner.size()*2);
    for(auto &p:inner){flat.push_back(p.first);flat.push_back(p.second);}
    const float(*fpts)[2]=reinterpret_cast<const float(*)[2]>(flat.data());
    poly.build(fpts,(int)inner.size(),r,g,b,y);
}

// ============================================================
//  CourseLayout
// ============================================================
CourseLayout::CourseLayout(){}
CourseLayout::~CourseLayout(){cleanup();}

static void buildRect(FlatPoly &poly,float x0,float x1,float z0,float z1,
                      float r,float g,float b,float y){
    float q[4][2]={{x0,z0},{x1,z0},{x1,z1},{x0,z1}};
    poly.build(q,4,r,g,b,y);
}

// ── Vertex-data builders (return CPU buffer, no GPU upload) ──────────────────
// Same layout as FlatPoly::build: [x y z  nx ny nz  r g b] per vertex.

static std::vector<float> polyVerts(const float pts[][2],int n,float r,float g,float b,float y){
    float simp[512][2];
    int sn=simplifyOutline(simp,pts,n,0.12f);
    if(sn<3) return {};
    std::vector<float> tris=triangulate(simp,sn);
    int tc=(int)tris.size()/6;
    std::vector<float> buf;buf.reserve(tc*3*9);
    for(int t=0;t<tc;++t)
        for(int v=0;v<3;++v){
            float px=tris[t*6+v*2],pz=tris[t*6+v*2+1];
            buf.push_back(px);buf.push_back(y);buf.push_back(pz);
            buf.push_back(0.f);buf.push_back(1.f);buf.push_back(0.f);
            buf.push_back(r);buf.push_back(g);buf.push_back(b);
        }
    return buf;
}

static std::vector<float> shrunkPolyVerts(const float pts[][2],int n,float shrink,float r,float g,float b,float y){
    float simp[512][2];
    int sn=simplifyOutline(simp,pts,n,0.12f);
    if(sn<3) return {};
    auto inner=shrinkPoly(simp,sn,shrink);
    std::vector<float> flat;flat.reserve(inner.size()*2);
    for(auto&p:inner){flat.push_back(p.first);flat.push_back(p.second);}
    const float(*fpts)[2]=reinterpret_cast<const float(*)[2]>(flat.data());
    return polyVerts(fpts,(int)inner.size(),r,g,b,y);
}

static std::vector<float> discVerts(float cx,float cz,float radius,float r,float g,float b,float y,int segs=12){
    std::vector<float> buf;buf.reserve(segs*3*9);
    auto push=[&](float px,float pz){
        buf.push_back(px);buf.push_back(y);buf.push_back(pz);
        buf.push_back(0.f);buf.push_back(1.f);buf.push_back(0.f);
        buf.push_back(r);buf.push_back(g);buf.push_back(b);
    };
    const float PI2=6.28318530f;
    for(int i=0;i<segs;++i){
        float a0=PI2*i/segs,a1=PI2*(i+1)/segs;
        push(cx,cz);
        push(cx+radius*std::cos(a0),cz+radius*std::sin(a0));
        push(cx+radius*std::cos(a1),cz+radius*std::sin(a1));
    }
    return buf;
}

void CourseLayout::build()
{
    if(m_built)return;
    m_built=true;

    buildRect(m_floor,MAP_X_MIN,MAP_X_MAX,MAP_Z_MIN,MAP_Z_MAX,COL_SAND,Y_FLOOR);

    m_dams[0].build(dam1_outline,dam1_outlineCount,COL_WATER,Y_WATER);
    m_dams[1].build(dam2_outline,dam2_outlineCount,COL_WATER,Y_WATER);
    m_dams[2].build(dam3_outline,dam3_outlineCount,COL_WATER,Y_WATER);

    // Rock beds: 3D boulders placed in RocksNode (see makeRockBedBoulders).

    // Per-hole green beds (sand + ring + centre) — one BatchedFlat each
    {
        const float* gbPtrs[18]={
            (float*)greenbed01_outline,(float*)greenbed02_outline,(float*)greenbed03_outline,
            (float*)greenbed04_outline,(float*)greenbed05_outline,(float*)greenbed06_outline,
            (float*)greenbed07_outline,(float*)greenbed08_outline,(float*)greenbed09_outline,
            (float*)greenbed10_outline,(float*)greenbed11_outline,(float*)greenbed12_outline,
            (float*)greenbed13_outline,(float*)greenbed14_outline,(float*)greenbed15_outline,
            (float*)greenbed16_outline,(float*)greenbed17_outline,(float*)greenbed18_outline
        };
        const int gbCounts[18]={
            greenbed01_outlineCount,greenbed02_outlineCount,greenbed03_outlineCount,
            greenbed04_outlineCount,greenbed05_outlineCount,greenbed06_outlineCount,
            greenbed07_outlineCount,greenbed08_outlineCount,greenbed09_outlineCount,
            greenbed10_outlineCount,greenbed11_outlineCount,greenbed12_outlineCount,
            greenbed13_outlineCount,greenbed14_outlineCount,greenbed15_outlineCount,
            greenbed16_outlineCount,greenbed17_outlineCount,greenbed18_outlineCount
        };
        for(int i=0;i<18;++i){
            const float(*pts)[2]=reinterpret_cast<const float(*)[2]>(gbPtrs[i]);
            int n=gbCounts[i];
            std::vector<float> buf;
            auto sand=polyVerts(pts,n,COL_GBSAND,Y_GBSAND);
            buf.insert(buf.end(),sand.begin(),sand.end());
            float cx=0,cz=0;
            for(int k=0;k<n;++k){cx+=pts[k][0];cz+=pts[k][1];}
            cx/=n;cz/=n;
            float maxR=0;
            for(int k=0;k<n;++k){float dx=pts[k][0]-cx,dz=pts[k][1]-cz;float d=std::sqrt(dx*dx+dz*dz);if(d>maxR)maxR=d;}
            if(maxR>0.8f){
                auto ring  =shrunkPolyVerts(pts,n,0.25f,COL_GBRING,Y_GBRING);
                auto centre=shrunkPolyVerts(pts,n,0.50f,COL_GBCEN, Y_GBCEN);
                buf.insert(buf.end(),ring.begin(),ring.end());
                buf.insert(buf.end(),centre.begin(),centre.end());
            }
            m_greenbed[i].upload(buf);
        }
    }

    // Per-hole putting greens
    {
        const float* holePtrs[18]={
            (float*)hole01_outline,(float*)hole02_outline,(float*)hole03_outline,
            (float*)hole04_outline,(float*)hole05_outline,(float*)hole06_outline,
            (float*)hole07_outline,(float*)hole08_outline,(float*)hole09_outline,
            (float*)hole10_outline,(float*)hole11_outline,(float*)hole12_outline,
            (float*)hole13_outline,(float*)hole14_outline,(float*)hole15_outline,
            (float*)hole16_outline,(float*)hole17_outline,(float*)hole18_outline
        };
        const int holeCounts[18]={
            hole01_outlineCount,hole02_outlineCount,hole03_outlineCount,
            hole04_outlineCount,hole05_outlineCount,hole06_outlineCount,
            hole07_outlineCount,hole08_outlineCount,hole09_outlineCount,
            hole10_outlineCount,hole11_outlineCount,hole12_outlineCount,
            hole13_outlineCount,hole14_outlineCount,hole15_outlineCount,
            hole16_outlineCount,hole17_outlineCount,hole18_outlineCount
        };
        for(int i=0;i<18;++i){
            const float(*pts)[2]=reinterpret_cast<const float(*)[2]>(holePtrs[i]);
            auto v=polyVerts(pts,holeCounts[i],COL_GREEN,Y_GREEN);
            m_green[i].upload(v);
        }
    }

    m_bridge[0].build(bridge01_outline,bridge01_outlineCount,COL_BRIDGE,Y_BRIDGE);
    m_bridge[1].build(bridge02_outline,bridge02_outlineCount,COL_BRIDGE,Y_BRIDGE);
    m_hut.build(hut_outline,hut_outlineCount,COL_HUT,Y_HUT);

    {
        std::vector<float> roadBuf;
        auto addRoad=[&](const float pts[][2],int n){
            if(n<3) return;
            auto v=polyVerts(pts,n,COL_ROAD,Y_ROAD);
            roadBuf.insert(roadBuf.end(),v.begin(),v.end());
        };
        addRoad(path_main_corridor,path_main_corridorCount);
        addRoad(path_right,path_rightCount);
        addRoad(path_middle,path_middleCount);
        addRoad(path_upper_corridor,path_upper_corridorCount);
        m_road.upload(roadBuf);
    }

    // Per-hole flag discs
    for(int i=0;i<18;++i){
        auto d=discVerts(holeFlags[i][0],holeFlags[i][1],0.20f,COL_FLAG,Y_FLAG,8);
        m_flag[i].upload(d);
    }
}

void CourseLayout::draw() const{
    m_floor.draw();
    m_road.draw();
    for(int i=0;i<3;++i)  m_dams[i].draw();
    for(int i=0;i<18;++i) m_greenbed[i].draw();
    for(int i=0;i<18;++i) m_green[i].draw();
    m_bridge[0].draw();m_bridge[1].draw();
    m_hut.draw();
    for(int i=0;i<18;++i) m_flag[i].draw();
}

void CourseLayout::cleanup(){
    m_floor.cleanup();m_road.cleanup();
    for(int i=0;i<3;++i)  m_dams[i].cleanup();
    for(int i=0;i<18;++i) m_greenbed[i].cleanup();
    for(int i=0;i<18;++i) m_green[i].cleanup();
    for(int i=0;i<18;++i) m_flag[i].cleanup();
    m_bridge[0].cleanup();m_bridge[1].cleanup();
    m_hut.cleanup();
    m_built=false;
}